const c = polyfit(state.train.map((p) => p[0]), state.train.map((p) => p[1]), state.deg);
return [
  line(linspace(-1, 1, 100).map((x) => [x, Math.sin(Math.PI * x)]), { color: 'gray', dashed: true }),
  points(state.test, { color: 'gray', opacity: 0.35, r: 3 }),
  line(linspace(-1, 1, 200).map((x) => [x, polyval(c, x)]), { color: 'orange' }),
  points(state.train, { id: 'train', draggable: true, color: 'blue', r: 6 })
];

const xs = state.train.map((p) => p[0]), ys = state.train.map((p) => p[1]);
const err = (c, data) => Math.log10(mse(data.map((p) => polyval(c, p[0])), data.map((p) => p[1])) + 1e-6);
const rows = range(1, 13).map((d) => { const c = polyfit(xs, ys, d); return [d, err(c, state.train), err(c, state.test)]; });
return [
  line(rows.map((r) => [r[0], r[1]]), { color: 'blue' }),
  line(rows.map((r) => [r[0], r[2]]), { color: 'red' }),
  vline(state.deg, { color: 'gray', dashed: true }),
  text(11.5, rows[10][1], 'train', { color: 'blue', align: 'right' }),
  text(11.5, rows[10][2], 'test', { color: 'red', align: 'right' })
];
